// seedInvoices adds one invoice to acme's customer per entry of at, each created at its time.
func seedInvoices(t *testing.T, st *store.Store, customerID string, at ...time.Time) []string {
	t.Helper()
	var ids []string
	for _, when := range at {
		inv, err := st.CreateInvoice(store.Invoice{AccountID: "acc_acme", CustomerID: customerID, Lines: []store.LineItem{{Description: "Pro plan", Quantity: 1, UnitCents: 100}}}, when)
		if err != nil {
			t.Fatal(err)
		}
		ids = append(ids, inv.ID)
	}
	return ids
}

type invoicePage struct {
	Items []struct {
		ID string `json:"id"`
	} `json:"items"`
	NextCursor string `json:"next_cursor"`
}

// listPage fetches one page of acme's invoices with the given query string and decodes it.
func listPage(t *testing.T, srv *api.Server, query string) (invoicePage, *httptest.ResponseRecorder) {
	t.Helper()
	r := do(t, srv, "GET", "/api/invoices?"+query, "key-acme", "")
	var p invoicePage
	if r.Code == http.StatusOK {
		if err := json.Unmarshal(r.Body.Bytes(), &p); err != nil {
			t.Fatalf("page %s: %v", r.Body, err)
		}
	}
	return p, r
}

// walkInvoices follows next_cursor from the first page until it is empty and returns every invoice ID in order.
func walkInvoices(t *testing.T, srv *api.Server, limit string) []string {
	t.Helper()
	var ids []string
	cursor := ""
	for pages := 0; ; pages++ {
		if pages > 1000 {
			t.Fatal("paging does not end")
		}
		query := "limit=" + limit
		if cursor != "" {
			query += "&cursor=" + url.QueryEscape(cursor)
		}
		p, r := listPage(t, srv, query)
		if r.Code != http.StatusOK {
			t.Fatalf("list %s: %d %s", query, r.Code, r.Body)
		}
		for _, it := range p.Items {
			ids = append(ids, it.ID)
		}
		if p.NextCursor == "" {
			return ids
		}
		cursor = p.NextCursor
	}
}

func TestInvoicesPageInCreationOrderWithTheDefaultLimit(t *testing.T) {
	srv, st := newServer(t)
	c, _ := st.CreateCustomer("acc_acme", "Jane", "jane@example.com", store.PlanPro, time.Now())
	base := time.Date(2026, 1, 1, 0, 0, 0, 0, time.UTC)
	var at []time.Time
	for i := 0; i < 45; i++ {
		// Two invoices share each timestamp, so ties must be broken by ID.
		at = append(at, base.Add(time.Duration(i/2)*time.Second))
	}
	seedInvoices(t, st, c.ID, at...)

	p, r := listPage(t, srv, "")
	if r.Code != http.StatusOK || len(p.Items) != 20 || p.NextCursor == "" {
		t.Fatalf("first page: %d, %d items, cursor %q", r.Code, len(p.Items), p.NextCursor)
	}
	var want []string
	for _, inv := range st.Invoices("acc_acme") {
		want = append(want, inv.ID)
	}
	got := walkInvoices(t, srv, "20")
	if len(got) != len(want) {
		t.Fatalf("walked %d invoices, want %d", len(got), len(want))
	}
	for i := range want {
		if got[i] != want[i] {
			t.Fatalf("position %d: got %s, want %s", i, got[i], want[i])
		}
	}
	if p, _ := listPage(t, srv, "limit=100"); len(p.Items) != 45 || p.NextCursor != "" {
		t.Fatalf("one page of 100: %d items, cursor %q", len(p.Items), p.NextCursor)
	}
}

func TestInvoicePagesNeitherSkipNorRepeatWhenInvoicesArrive(t *testing.T) {
	srv, st := newServer(t)
	c, _ := st.CreateCustomer("acc_acme", "Jane", "jane@example.com", store.PlanPro, time.Now())
	base := time.Date(2026, 1, 1, 0, 0, 0, 0, time.UTC)
	ids := seedInvoices(t, st, c.ID, base, base, base.Add(time.Second), base.Add(time.Second), base.Add(2*time.Second))

	p, _ := listPage(t, srv, "limit=2")
	var got []string
	for _, it := range p.Items {
		got = append(got, it.ID)
	}
	// New invoices arrive between page requests: one at the last position's timestamp, others later.
	ids = append(ids, seedInvoices(t, st, c.ID, base.Add(2*time.Second), base.Add(3*time.Second), base.Add(3*time.Second))...)
	for cursor := p.NextCursor; cursor != ""; {
		p, r := listPage(t, srv, "limit=2&cursor="+url.QueryEscape(cursor))
		if r.Code != http.StatusOK {
			t.Fatalf("page: %d %s", r.Code, r.Body)
		}
		for _, it := range p.Items {
			got = append(got, it.ID)
		}
		cursor = p.NextCursor
	}
	if len(got) != len(ids) {
		t.Fatalf("got %d invoices %v, want %d %v", len(got), got, len(ids), ids)
	}
	for i := range ids {
		if got[i] != ids[i] {
			t.Fatalf("position %d: got %s, want %s", i, got[i], ids[i])
		}
	}
}

func TestInvoicePageLimitMustBeAWholeNumberFromOneToOneHundred(t *testing.T) {
	srv, _ := newServer(t)
	for _, bad := range []string{"0", "-1", "101", "abc", "", "1.5", "1e2", " 5"} {
